UPDATE notices
SET category = #{category},
    title = #{title},
    content = #{content},
    updated_at = SYSDATE,
    editor_user_id = #{isEditorUserId},
    is_pinned = #{isPinned},
    attachment_group_id = #{attachmentGroupId}

    ,is_deleted = #{isDeleted}

WHERE notice_id = #{noticeId}

mapper.select:
SELECT b.* FROM (SELECT ROWNUM AS num, A.* FROM (SELECT COUNT(*) OVER() AS task_counts, n.title, u.user_name, n.created_at, n.is_pinned, n.is_deleted, n.notice_id, t.type_name FROM notices n JOIN projects p ON n.project_id = p.project_id JOIN users u ON n.created_by = u.user_id LEFT JOIN task_types t ON n.category = t.task_type_id WHERE (p.project_id=#{projectId} OR p.parent_project_id = #{projectId})
AND n.created_by = #{userId}
AND n.category = #{category}
AND n.created_at >= #{startDate}
AND n.created_at <= #{endDate}
AND n.title LIKE '%' || #{search} || '%'
ORDER BY n.is_deleted DESC, n.is_pinned, created_at DESC) A WHERE ROWNUM BETWEEN 1 AND #{endNum})b WHERE b.num >= #{startNum}

mapper.update:
UPDATE notices
SET is_deleted = #{isDeleted}
WHERE notice_id = #{noticeId}
